      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Infinite Dual-Direction Partner Logo Marquee</title>\n  <style>\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  width: 100%;\n  height: 100%;\n  background: #09090b;\n  color: #fafafa;\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", sans-serif;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n}\n\n.marquee-section {\n  width: 100%;\n  max-width: 1200px;\n  padding: 40px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 24px;\n}\n\n.marquee-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 0 32px;\n}\n\n.marquee-label {\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: rgba(250, 250, 250, 0.5);\n}\n\n.marquee-btn {\n  appearance: none;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  color: #fafafa;\n  padding: 6px 14px;\n  border-radius: 999px;\n  font-size: 12px;\n  cursor: pointer;\n}\n\n.clients-marquee {\n  position: relative;\n  display: flex;\n  overflow: hidden;\n  user-select: none;\n  gap: 20px;\n  mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);\n  -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);\n}\n\n.clients-marquee__group {\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  justify-content: space-around;\n  gap: 20px;\n  min-width: 100%;\n  animation: scroll-left var(--marquee-duration, 26s) linear infinite;\n}\n\n.clients-marquee--reverse .clients-marquee__group {\n  animation-direction: reverse;\n}\n\n.clients-marquee:hover .clients-marquee__group {\n  animation-play-state: paused;\n}\n\n.clients-marquee__item {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 14px 26px;\n  border-radius: 12px;\n  background: rgba(255, 255, 255, 0.03);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  color: rgba(250, 250, 250, 0.72);\n  font-size: 15px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  white-space: nowrap;\n  transition: border-color 0.2s, color 0.2s, background 0.2s, transform 0.2s;\n}\n\n.clients-marquee__item:hover {\n  border-color: rgba(167, 139, 250, 0.5);\n  background: rgba(167, 139, 250, 0.08);\n  color: #ffffff;\n  transform: translateY(-2px);\n}\n\n.clients-marquee__dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n}\n\n@keyframes scroll-left {\n  from { transform: translateX(0); }\n  to { transform: translateX(calc(-100% - 20px)); }\n}\n\n</style>\n</head>\n<body>\n  <section class=\"marquee-section\">\n    <div class=\"marquee-header\">\n      <span class=\"marquee-label\">Trusted by Global Clubs, Federations &amp; Brands</span>\n      <button type=\"button\" class=\"marquee-btn\" id=\"speed-toggle\">Speed: Normal (1x)</button>\n    </div>\n    <div class=\"clients-marquee\" id=\"marquee-row-1\"></div>\n    <div class=\"clients-marquee clients-marquee--reverse\" id=\"marquee-row-2\"></div>\n  </section>\n  <script>\n/**\n * Infinite Dual-Direction Partner Logo Marquee\n * Extracted from carousel-gallery-play/app.js\n */\n(function () {\n  const ROW_1 = [\n    { name: 'AFC AJAX', color: '#ef4444' },\n    { name: 'CLUB BRUGGE', color: '#3b82f6' },\n    { name: 'COMO 1907', color: '#0ea5e9' },\n    { name: 'DAZN BROADCAST', color: '#eab308' },\n    { name: 'HOKA PERFORMANCE', color: '#38bdf8' },\n    { name: 'ADIDAS ORIGINALS', color: '#10b981' },\n    { name: 'BELGIAN RED DEVILS', color: '#f97316' }\n  ];\n\n  const ROW_2 = [\n    { name: 'ROYAL ANTWERP FC', color: '#f43f5e' },\n    { name: 'DPG MEDIA', color: '#a855f7' },\n    { name: 'BNXT LEAGUE', color: '#6366f1' },\n    { name: 'VFL WOLFSBURG', color: '#22c55e' },\n    { name: 'AL QADSIAH FC', color: '#f59e0b' },\n    { name: 'PLAY SPORTS', color: '#14b8a6' },\n    { name: 'JOUER STUDIO', color: '#ec4899' }\n  ];\n\n  function populateRow(elId, items) {\n    const container = document.getElementById(elId);\n    if (!container) return;\n    const renderGroup = (isClone) => `\n      <div class=\"clients-marquee__group\"${isClone ? ' aria-hidden=\"true\"' : ''}>\n        ${items\n          .map(\n            (c) => `\n          <div class=\"clients-marquee__item\">\n            <span class=\"clients-marquee__dot\" style=\"background:${c.color}\"></span>\n            <span>${c.name}</span>\n          </div>`\n          )\n          .join('')}\n      </div>`;\n    container.innerHTML = renderGroup(false) + renderGroup(true);\n  }\n\n  populateRow('marquee-row-1', ROW_1);\n  populateRow('marquee-row-2', ROW_2);\n\n  const btn = document.getElementById('speed-toggle');\n  let fast = false;\n  if (btn) {\n    btn.addEventListener('click', () => {\n      fast = !fast;\n      document.documentElement.style.setProperty('--marquee-duration', fast ? '12s' : '26s');\n      btn.textContent = fast ? 'Speed: Turbo (2.2x)' : 'Speed: Normal (1x)';\n    });\n  }\n})();\n\n</script>\n</body>\n</html>\n",
