      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Filterable Roster & Portrait Hover Showcase</title>\n  <style>\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  width: 100%;\n  min-height: 100%;\n  background: #09090b;\n  color: #fafafa;\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", sans-serif;\n}\n\n.ath-section {\n  max-width: 1120px;\n  margin: 0 auto;\n  padding: 36px 28px;\n}\n\n.ath-top {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  align-items: flex-end;\n  gap: 16px;\n  margin-bottom: 28px;\n}\n\n.ath-heading {\n  font-size: clamp(22px, 3vw, 34px);\n  font-weight: 800;\n  letter-spacing: -0.03em;\n}\n\n.ath-heading span {\n  color: #ff3700;\n}\n\n.ath-tabs {\n  display: flex;\n  gap: 8px;\n  background: rgba(255, 255, 255, 0.04);\n  padding: 4px;\n  border-radius: 999px;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n.athletes-tab-btn {\n  appearance: none;\n  background: transparent;\n  border: none;\n  color: rgba(250, 250, 250, 0.6);\n  padding: 8px 16px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, color 0.2s;\n}\n\n.athletes-tab-btn[aria-selected=\"true\"] {\n  background: #ff3700;\n  color: #ffffff;\n}\n\n.ath-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 18px;\n}\n\n.portrait-card {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  animation: card-in 0.35s cubic-bezier(0.22, 1, 0.36, 1) both;\n}\n\n@keyframes card-in {\n  from { opacity: 0; transform: translateY(10px) scale(0.97); }\n  to { opacity: 1; transform: none; }\n}\n\n.portrait-card__media {\n  position: relative;\n  aspect-ratio: 3 / 4;\n  border-radius: 12px;\n  overflow: hidden;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  background-size: cover;\n  background-position: center;\n}\n\n.portrait-card__badge {\n  position: absolute;\n  top: 12px;\n  left: 12px;\n  padding: 4px 10px;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  background: rgba(9, 9, 11, 0.78);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  backdrop-filter: blur(6px);\n}\n\n.portrait-card__overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(255, 55, 0, 0.85);\n  color: #ffffff;\n  text-decoration: none;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  padding: 16px;\n  opacity: 0;\n  transition: opacity 0.25s ease;\n}\n\n.portrait-card__media:hover .portrait-card__overlay {\n  opacity: 1;\n}\n\n.portrait-card__overlay-top {\n  display: flex;\n  justify-content: flex-end;\n}\n\n.portrait-card__overlay-center {\n  text-align: center;\n  font-size: 13px;\n  font-weight: 800;\n  letter-spacing: 0.12em;\n}\n\n.portrait-card__name {\n  font-size: 15px;\n  font-weight: 700;\n}\n\n.portrait-card__role {\n  font-size: 12px;\n  color: rgba(250, 250, 250, 0.55);\n}\n\n</style>\n</head>\n<body>\n  <section class=\"ath-section\" id=\"athletes\">\n    <div class=\"ath-top\">\n      <h2 class=\"ath-heading\">TALENT &amp; <span>ROSTER</span></h2>\n      <div class=\"ath-tabs\" role=\"tablist\">\n        <button type=\"button\" class=\"athletes-tab-btn\" role=\"tab\" aria-selected=\"true\" data-filter=\"all\">All Talent (8)</button>\n        <button type=\"button\" class=\"athletes-tab-btn\" role=\"tab\" aria-selected=\"false\" data-filter=\"exclusive\">Exclusive (4)</button>\n        <button type=\"button\" class=\"athletes-tab-btn\" role=\"tab\" aria-selected=\"false\" data-filter=\"creative\">Creators (2)</button>\n      </div>\n    </div>\n    <div class=\"ath-grid\" id=\"athletes-rail\"></div>\n  </section>\n  <script>\n/**\n * Filterable Roster & Portrait Hover Showcase\n * Extracted from carousel-gallery-play/app.js\n */\n(function () {\n  const ROSTER = [\n    { name: 'Kaye Furo', role: 'Club Brugge // Forward', category: 'exclusive', grad: 'linear-gradient(150deg, #1d4ed8, #0f172a)' },\n    { name: 'Rein Van Helden', role: 'Royal Antwerp FC // Defender', category: 'exclusive', grad: 'linear-gradient(150deg, #e11d48, #1f2937)' },\n    { name: 'Thibaud Verlinden', role: 'OH Leuven // Winger', category: 'all', grad: 'linear-gradient(150deg, #ea580c, #18181b)' },\n    { name: 'Sebastiaan Bornauw', role: 'VfL Wolfsburg // Center Back', category: 'exclusive', grad: 'linear-gradient(150deg, #16a34a, #052e16)' },\n    { name: 'Ignace Van Der Brempt', role: 'Como 1907 // Fullback', category: 'all', grad: 'linear-gradient(150deg, #0284c7, #0c4a6e)' },\n    { name: 'Daan Dierckx', role: 'Standard Liège // Defender', category: 'exclusive', grad: 'linear-gradient(150deg, #dc2626, #450a0a)' },\n    { name: 'Pieter Slembrouck', role: 'Founder & Creative Director', category: 'creative', grad: 'linear-gradient(150deg, #9333ea, #2e1065)' },\n    { name: 'Jerry Lawyer', role: 'Visual Director & Photographer', category: 'creative', grad: 'linear-gradient(150deg, #eab308, #422006)' }\n  ];\n\n  const rail = document.getElementById('athletes-rail');\n  const tabs = document.querySelectorAll('.athletes-tab-btn');\n  if (!rail) return;\n\n  function render(filter) {\n    const list = ROSTER.filter((item) => filter === 'all' || item.category === filter);\n    rail.innerHTML = list\n      .map(\n        (ath) => `\n      <article class=\"portrait-card\" data-category=\"${ath.category}\">\n        <div class=\"portrait-card__media\" style=\"background-image: ${ath.grad};\">\n          <span class=\"portrait-card__badge\">${ath.category.toUpperCase()}</span>\n          <a href=\"#contact\" class=\"portrait-card__overlay\" onclick=\"event.preventDefault()\">\n            <div class=\"portrait-card__overlay-top\">\n              <svg width=\"14\" height=\"14\" viewBox=\"0 0 12 12\"><path d=\"M1 11L11 1M11 1H3M11 1V9\" stroke=\"#ffffff\" stroke-width=\"1.6\" fill=\"none\"/></svg>\n            </div>\n            <div class=\"portrait-card__overlay-center\">COLLABORATE ↗</div>\n            <div></div>\n          </a>\n        </div>\n        <div>\n          <h3 class=\"portrait-card__name\">${ath.name}</h3>\n          <p class=\"portrait-card__role\">${ath.role}</p>\n        </div>\n      </article>`\n      )\n      .join('');\n  }\n\n  render('all');\n\n  tabs.forEach((btn) => {\n    btn.addEventListener('click', () => {\n      const filter = btn.getAttribute('data-filter') || 'all';\n      tabs.forEach((b) => b.setAttribute('aria-selected', String(b === btn)));\n      render(filter);\n    });\n  });\n})();\n\n</script>\n</body>\n</html>\n",
